research_workspace.actual_adopted_css:
/* Scoped adaptation of MIT-licensed Tufte CSS. Source in ../tufte-source.css;
   notice in TUFTE-LICENSE. Retained: float/clear/negative-margin relationship.
   Adapted: 66% reading region, 42% notes; narrow-screen notes always visible. */
.folio-prose{width:66%;counter-reset:sidenote-counter}
.folio-prose .sidenote{float:right;clear:right;margin-right:-51.5%;width:42%;margin-top:.3rem;margin-bottom:0;font-size:.75rem;line-height:1.65;vertical-align:baseline;position:relative}
.folio-prose .sidenote-number{counter-increment:sidenote-counter}
.folio-prose .sidenote-number::after{content:counter(sidenote-counter);font-family:var(--mono);font-size:.65rem;position:relative;top:-.4rem;left:.15rem;color:var(--accent)}
.folio-prose .sidenote::before{content:counter(sidenote-counter) ' / ';font-family:var(--mono);font-size:.65rem;color:var(--accent)}
.folio-prose::after{content:'';display:block;clear:both}
@media(max-width:1100px){.folio-prose{width:100%}.folio-prose .sidenote{float:none;display:block;width:100%;margin:12px 0 16px;padding:10px 12px;border-left:2px solid var(--line);font-size:.75rem}}

authored_film.actual_timeline_code:
/**
 * Authored 12-second timeline. Units are source SVG units (1100 × 355).
 * Change timing and trajectories here; change words and geometry in source.svg.
 * The source is fully settled, with unmodified paints and positions, 6.85–10.9s.
 * The last 0.3s and first 0.3s share the same quiet study state.
 */
const stage = document.querySelector('#stage');
const svgText = await fetch('assets/stage.svg').then(r => { if (!r.ok) throw new Error('Artwork unavailable'); return r.text(); });
stage.innerHTML = svgText;
const svg = stage.querySelector('svg'), $ = id => svg.querySelector('#' + id);
await Promise.all([...svg.querySelectorAll('image')].map(el => {
  const im = new Image(); im.src = el.getAttribute('href'); return im.decode();
}));
const g = window.gsap;
if (!g) throw new Error('GSAP runtime unavailable');
const DUR = 12;

function group(id, ids) {
  const wrap = document.createElementNS(svg.namespaceURI, 'g'); wrap.id = id;
  $(ids[0]).before(wrap);
  ids.forEach(name => wrap.append($(name)));
  return wrap;
}
function clone(id, name) {
  const el = $(id).cloneNode(true); el.id = name;
  el.removeAttribute('data-source-text'); el.setAttribute('aria-hidden', 'true');
  svg.append(el); return el;
}
function rect(id, attrs) {
  const el = document.createElementNS(svg.namespaceURI, 'rect'); el.id = id;
  for (const [key, value] of Object.entries(attrs)) el.setAttribute(key, value);
  el.setAttribute('aria-hidden', 'true'); svg.append(el); return el;
}
const selectedIds = ['select-type', 'select-divider', 'select-line-1', 'select-line-2', 'select-line-3', 'select-dot', 'select-check', 'select-fit'];
const realizedIds = ['realize-page', 'realize-title', 'realize-rule', 'realize-line-1', 'realize-line-2', 'realize-line-3', 'realize-button', 'realize-button-text'];
const selected = selectedIds.map($), realized = realizedIds.map($);
const selectGroup = group('selected-content', selectedIds);
const realizeGroup = group('realized-content', realizedIds);
const scan = rect('study-scan', { x: 526, y: 175, width: 135, height: 3, fill: '#22665a' });
const pattern = clone('study-pattern', 'pattern-handoff');
const accent = clone('select-fit', 'accent-handoff');
const lines = [1, 2, 3].map(i => clone(`select-line-${i}`, `line-handoff-${i}`));
const type = clone('select-type', 'type-handoff');
const action = rect('action-handoff', { x: 717, y: 250, width: 16, height: 16, rx: 8, fill: '#22665a' });
const transient = [scan, pattern, accent, ...lines, type, action];

g.set([...selected, ...realized, ...transient], { opacity: 0 });
g.set($('select-type'), { y: 6 });
g.set($('select-dot'), { scale: 0.6, svgOrigin: '725 258' });
g.set($('select-fit'), { scaleX: 0, svgOrigin: '741 258' });
g.set($('select-divider'), { scaleY: 0, svgOrigin: '770 135' });
g.set($('realize-page'), { y: 8 });
g.set(type, { svgOrigin: '719 164' });
for (const i of [1, 2]) {
  g.set($(`arrow-${i}-stem`), { strokeDasharray: 23, strokeDashoffset: 23 });
  g.set($(`arrow-${i}-head`), { opacity: 0 });
}
const checkLength = $('select-check').getTotalLength();
g.set($('select-check'), { strokeDasharray: checkLength, strokeDashoffset: checkLength });

const tl = g.timeline({ paused: true, repeat: -1, defaults: { ease: 'power2.inOut' } });
tl.addLabel('study', 0).addLabel('select', 2.4).addLabel('realize', 4.15).addLabel('settled', 6.85).addLabel('return', 10.9);

// 01 Study: reading moves down the actual source rules; its green pattern persists.
tl.to(scan, { opacity: 0.9, duration: 0.22 }, 0.35)
  .to(scan, { attr: { y: 186, width: 117 }, duration: 0.35 }, 0.65)
  .to(scan, { attr: { y: 197, width: 125 }, duration: 0.35 }, 1.0)
  .to(scan, { opacity: 0, duration: 0.25 }, 1.35);
tl.to($('study-card'), { attr: { stroke: '#22665a' }, duration: 0.3 }, 0.35)
  .to($('study-card'), { attr: { stroke: '#b8c6bb' }, duration: 0.45 }, 2.5);

// A copy of the researched pattern crosses the first arrow, then fits the selection.
tl.set(pattern, { opacity: 1 }, 1.6)
  .to(pattern, { attr: { x: 677, y: 206.2, width: 23 }, duration: 0.42 }, 1.6)
  .to(pattern, { attr: { x: 782, y: 138, width: 71, fill: '#b8c6bb' }, duration: 0.64 }, 2.02)
  .to($('arrow-1-stem'), { strokeDashoffset: 0, duration: 0.3 }, 1.82)
  .to($('arrow-1-head'), { opacity: 1, duration: 0.18 }, 2.02)
  .set($('select-line-1'), { opacity: 1 }, 2.66)
  .set(pattern, { opacity: 0 }, 2.66);

// 02 Select: the typographic system resolves; the check follows the decision.
tl.to($('select-type'), { opacity: 1, y: 0, duration: 0.5, ease: 'power2.out' }, 2.42)
  .to($('select-divider'), { opacity: 1, scaleY: 1, duration: 0.5 }, 2.55)
  .to([$ ('select-line-2'), $('select-line-3')], { opacity: 1, duration: 0.25, stagger: 0.15 }, 2.78)
  .to($('select-dot'), { opacity: 1, scale: 1, duration: 0.3, ease: 'power2.out' }, 3.18)
  .set($('select-check'), { opacity: 1 }, 3.4)
  .to($('select-check'), { strokeDashoffset: 0, duration: 0.28 }, 3.4)
  .to($('select-fit'), { opacity: 1, scaleX: 1, duration: 0.5 }, 3.32);
tl.to($('select-card'), { attr: { stroke: '#22665a' }, duration: 0.3 }, 2.45)
  .to($('select-card'), { attr: { stroke: '#b8c6bb' }, duration: 0.5 }, 4.1);

// 03 Realize: selected tokens take the positions and proportions of the final page.
tl.to($('realize-page'), { opacity: 1, y: 0, duration: 0.5 }, 4.12)
  .to($('arrow-2-stem'), { strokeDashoffset: 0, duration: 0.32 }, 4.22)
  .to($('arrow-2-head'), { opacity: 1, duration: 0.18 }, 4.46);
tl.set(accent, { opacity: 1, attr: { fill: '#22665a' } }, 4.2)
  .to(accent, { attr: { x: 869, y: 215, width: 23, height: 3 }, duration: 0.45 }, 4.2)
  .to(accent, { attr: { x: 924, y: 173, width: 107 }, duration: 0.5 }, 4.65)
  .set($('realize-rule'), { opacity: 1 }, 5.15)
  .set(accent, { opacity: 0 }, 5.15);
lines.forEach((line, i) => {
  const start = 4.6 + i * 0.14, finish = start + 0.82;
  tl.set(line, { opacity: 1, attr: { fill: '#22665a' } }, start)
    .to(line, { attr: { x: 924, y: [188, 198, 208][i], width: [107, 91, 98][i], height: 2, fill: '#b8c6bb' }, duration: 0.82 }, start)
    .set($(`realize-line-${i+1}`), { opacity: 1 }, finish)
    .set(line, { opacity: 0 }, finish);
});
tl.set(type, { opacity: 0.72 }, 5.15)
  // Carry the specimen through the open lower area, clear of selection rules,
  // then up the inter-card gap into the header. Readable text never doubles.
  .to(type, { x: 36, y: 75, scale: 0.65, duration: 0.27 }, 5.15)
  .to(type, { x: 164, y: 75, scale: 18 / 42, duration: 0.28, ease: 'power1.inOut' }, 5.42)
  .to(type, { x: 164, y: -3, duration: 0.21, ease: 'power1.inOut' }, 5.70)
  .to(type, { x: 205, y: -3, opacity: 0.65, duration: 0.12, ease: 'power2.out' }, 5.91)
  .to(type, { opacity: 0, duration: 0.07 }, 6.03)
  .to($('realize-title'), { opacity: 1, duration: 0.26 }, 6.12);
tl.set(action, { opacity: 1 }, 5.68)
  .to(action, { attr: { x: 924, y: 246, width: 107, height: 14, rx: 2 }, duration: 0.86 }, 5.68)
  .set($('realize-button'), { opacity: 1 }, 6.54)
  .set(action, { opacity: 0 }, 6.54)
  .to($('realize-button-text'), { opacity: 1, duration: 0.3 }, 6.54);
tl.to($('realize-card'), { attr: { stroke: '#22665a' }, duration: 0.35 }, 4.2)
  .to($('realize-card'), { attr: { stroke: '#b8c6bb' }, duration: 0.45 }, 6.4);

// Hold the supplied composition, untouched, for just over four seconds.
// Reset only the working material; the title, frame, labels and card anchors persist.
tl.to(realizeGroup, { opacity: 0, y: 10, duration: 0.55 }, 10.9)
  .to(selectGroup, { opacity: 0, duration: 0.5 }, 11.05)
  .to([$ ('arrow-1-stem'), $('arrow-2-stem'), $('arrow-1-head'), $('arrow-2-head')], { opacity: 0, duration: 0.45 }, 11.05)
  .set([...selected, ...realized], { opacity: 0 }, 11.6)
  .set(selectGroup, { opacity: 1 }, 11.62)
  .set(realizeGroup, { opacity: 1, y: 0 }, 11.62)
  .set($('select-type'), { y: 6 }, 11.62)
  .set($('select-dot'), { scale: 0.6 }, 11.62)
  .set($('select-fit'), { scaleX: 0 }, 11.62)
  .set($('select-divider'), { scaleY: 0 }, 11.62)
  .set($('select-check'), { strokeDashoffset: checkLength }, 11.62)
  .set($('realize-page'), { y: 8 }, 11.62)
  .set([$ ('arrow-1-stem'), $('arrow-2-stem')], { opacity: 1, strokeDashoffset: 23 }, 11.62)
  .set({}, {}, DUR);

const listeners = new Set();
const api = {
  ready: true, duration: DUR, timeline: tl,
  seek(t) { tl.pause().totalTime(Math.min(DUR, Math.max(0, +t))); update(); },
  play() { if (tl.time() >= DUR) tl.totalTime(0); tl.play(); update(); },
  pause() { tl.pause(); update(); },
  restart() { tl.restart(); update(); },
  poster() { this.seek(8); },
  onChange(fn) { listeners.add(fn); fn({ time: tl.time(), paused: tl.paused() }); return () => listeners.delete(fn); },
};
function update() { listeners.forEach(fn => fn({ time: tl.time(), paused: tl.paused() })); }
tl.eventCallback('onUpdate', update);
tl.eventCallback('onComplete', update);
window.film = api;
tl.totalTime(0).pause();
document.dispatchEvent(new Event('filmready'));
